import fs from 'node:fs';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';import * as a from './runtime.mjs';import * as c from '../../dist/index.js';
const read=p=>JSON.parse(fs.readFileSync(p)),input={scenario:read('fixtures/operations/picking-packing-burst.json'),executionConfig:read('fixtures/operations/picking-packing-burst.runconfig.json').executionConfig};const report=c.runOperationsExperiment(input),frozen=a.runOperationsExperiment(input);assert.deepEqual(frozen,report);assert.equal(a.verifyOperationsExperiment(report).ok,true);assert.equal(c.verifyOperationsExperiment(frozen).ok,true);
const guards=[];for(const mode of ['source','version'])guards.push(execFileSync(process.execPath,['packages/simulation/archive/0.1.1/guard-check.mjs',mode],{encoding:'utf8'}).trim());
const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),m=read('packages/simulation/archive/0.1.1/manifest.json');for(const [p,h]of Object.entries(m.recipeHashes))assert.equal(sha(fs.readFileSync(p)),h);assert.equal(sha(fs.readFileSync(m.bundle.path)),m.bundle.sha256);for(const [p,h]of Object.entries(m.preservedOldArchiveHashes))assert.equal(sha(fs.readFileSync(p)),h);
const text=fs.readFileSync(m.bundle.path,'utf8');assert.ok(!/\bfrom\s*["']|\bimport\s*\(|\brequire\s*\(/.test(text));assert.equal(a.createOperationsControllerForVersion,undefined);fs.writeFileSync('evidence/sanitized/r2-runtime11/extra-proof.json',JSON.stringify({experimentCurrentEqualsFrozen:true,crossVerification:true,guards,recipeHashesVerified:true,oldArchiveRawBytesPreserved:true,standaloneEsmNoExternalImports:true,noRuntimeSelectorExport:true,licenseSha256:sha(fs.readFileSync('packages/simulation/archive/0.1.1/LICENSES.md')),bundleSha256:m.bundle.sha256},null,2));console.log('extra guards, experiment cross-replay and integrity passed');
